"""Actual mlx5 native peer close/lease extraction, no hardware or VM.

The two unchanged upstream void destroy wrappers are fixture inputs for the
non-peer compatibility wrappers; checked peer close sends the real extracted
firmware call directly. The real owner helper is a boundary in this leaf test.
Outer channel/CQ, rep/esw and owner-reference proofs require separate tests.
"""
import argparse,ast,json,pathlib,re,shutil,subprocess,sys,tempfile
from pathlib import Path
from types import SimpleNamespace
HERE=Path(__file__).resolve().parent
def function(text, name):
    m = re.search(r'(?m)^(?:static\s+)?(?:inline\s+)?(?:void|int|bool|u32|struct\s+\w+\s*\*)\s*' + re.escape(name) + r'\s*\([^;{}]*\)\s*\{', text)
    if not m:
        raise ValueError('Missing production function: ' + name)
    start = m.start(); brace = m.end() - 1; depth = 1; i = brace + 1
    while depth:
        if text.startswith('/*', i): i = text.index('*/', i + 2) + 2; continue
        if text.startswith('//', i): i = text.index('\n', i + 2); continue
        if text[i] in '\"\'':
            quote = text[i]; i += 1
            while text[i] != quote:
                i += 2 if text[i] == '\\' else 1
            i += 1; continue
        depth += (text[i] == '{') - (text[i] == '}'); i += 1
    return text[start:i] + '\n', [text.count('\n', 0, start) + 1, text.count('\n', 0, i) + 1]

def literal(path, variable):
    for node in ast.parse(path.read_text()).body:
        if isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == variable for t in node.targets):
            return ast.literal_eval(node.value)
    raise ValueError(variable)

